CREATE TABLE authorities (
    id VARCHAR(36) COLLATE "C" NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    version BIGINT NOT NULL,
    kind VARCHAR(32) COLLATE "C" NOT NULL,
    name TEXT NOT NULL,
    management_parent_id VARCHAR(36) COLLATE "C",
    issuance_state VARCHAR(32) COLLATE "C" NOT NULL,
    issuance_certificate_id VARCHAR(36) COLLATE "C",
    archived_at BIGINT,
    PRIMARY KEY (id),
    CHECK (kind IN ('root','intermediate','bootstrap')),
    CHECK (issuance_state IN ('inventory','enabled','stopped')),
    CHECK ((kind = 'intermediate' AND management_parent_id IS NOT NULL) OR (kind IN ('root','bootstrap') AND management_parent_id IS NULL)),
    CHECK (length(id) = 36),
    CHECK (version >= 0),
    CHECK (length(kind) <= 32),
    CHECK (length(management_parent_id) = 36),
    CHECK (length(issuance_state) <= 32),
    CHECK (length(issuance_certificate_id) = 36)
);

CREATE TABLE ca_key_generations (
    id VARCHAR(36) COLLATE "C" NOT NULL,
    created_at BIGINT NOT NULL,
    authority_id VARCHAR(36) COLLATE "C" NOT NULL,
    key_material_id VARCHAR(36) COLLATE "C" NOT NULL,
    generation_no BIGINT NOT NULL,
    key_destroyed_at BIGINT,
    PRIMARY KEY (id),
    UNIQUE (authority_id, generation_no),
    UNIQUE (key_material_id),
    CHECK (length(id) = 36),
    CHECK (length(authority_id) = 36),
    CHECK (length(key_material_id) = 36),
    CHECK (generation_no >= 0)
);

CREATE TABLE certificates (
    id VARCHAR(36) COLLATE "C" NOT NULL,
    created_at BIGINT NOT NULL,
    der_sha256 VARCHAR(64) COLLATE "C" NOT NULL,
    der BYTEA NOT NULL,
    key_material_id VARCHAR(36) COLLATE "C" NOT NULL,
    issuer_ca_key_generation_id VARCHAR(36) COLLATE "C" NOT NULL,
    serial_hex VARCHAR(40) COLLATE "C" NOT NULL,
    not_before BIGINT NOT NULL,
    not_after BIGINT NOT NULL,
    subject_json TEXT NOT NULL,
    extensions_json TEXT NOT NULL,
    origin VARCHAR(32) COLLATE "C" NOT NULL,
    created_by VARCHAR(36) COLLATE "C",
    PRIMARY KEY (id),
    UNIQUE (der_sha256),
    UNIQUE (issuer_ca_key_generation_id, serial_hex),
    CHECK (not_after > not_before),
    CHECK (serial_hex <> '0'),
    CHECK (origin IN ('generated','imported')),
    CHECK (length(id) = 36),
    CHECK (length(der_sha256) = 64),
    CHECK (length(key_material_id) = 36),
    CHECK (length(issuer_ca_key_generation_id) = 36),
    CHECK (length(serial_hex) BETWEEN 1 AND 40),
    CHECK ((length(serial_hex) = 1 OR substr(serial_hex,1,1) <> '0')),
    CHECK (serial_hex ~ '^[0-9a-f]+$'),
    CHECK (length(origin) <= 32),
    CHECK (length(created_by) = 36)
);

CREATE TABLE ca_certificates (
    certificate_id VARCHAR(36) COLLATE "C" NOT NULL,
    ca_key_generation_id VARCHAR(36) COLLATE "C" NOT NULL,
    issuer_ca_certificate_id VARCHAR(36) COLLATE "C",
    PRIMARY KEY (certificate_id),
    CHECK (length(certificate_id) = 36),
    CHECK (length(ca_key_generation_id) = 36),
    CHECK (length(issuer_ca_certificate_id) = 36)
);

