    id VARCHAR(36) COLLATE "C" NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    version BIGINT NOT NULL,
    name TEXT NOT NULL,
    purpose VARCHAR(32) COLLATE "C" NOT NULL,
    management_authority_id VARCHAR(36) COLLATE "C" NOT NULL,
    current_certificate_id VARCHAR(36) COLLATE "C",
    current_key_generation_id VARCHAR(36) COLLATE "C",
    validity_policy_json TEXT NOT NULL,
    rotate_every BIGINT NOT NULL,
    archived_at BIGINT,
    PRIMARY KEY (id),
    CHECK (purpose IN ('distributed','internal_tls','bootstrap_tls')),
    CHECK (rotate_every BETWEEN 1 AND 100),
    CHECK (length(id) = 36),
    CHECK (version >= 0),
    CHECK (length(purpose) <= 32),
    CHECK (length(management_authority_id) = 36),
    CHECK (length(current_certificate_id) = 36),
    CHECK (length(current_key_generation_id) = 36)
