CREATE TABLE leaf_key_generations (
    id VARCHAR(36) COLLATE "C" NOT NULL,
    created_at BIGINT NOT NULL,
    series_id VARCHAR(36) COLLATE "C" NOT NULL,
    key_material_id VARCHAR(36) COLLATE "C" NOT NULL,
    generation_no BIGINT NOT NULL,
    renewal_count BIGINT NOT NULL,
